window.receiveProjectSource({"path": "test/integration/entity_classification/test_table_writes_replay_regressions.py", "lines": ["import asyncio", "from datetime import UTC, datetime", "from uuid import UUID, uuid4", "", "import pytest", "from accelerate_models.common.models.enum import AccountType", "from accelerate_models.documents.app.models import DocContent, DocEntityMap, Document", "from accelerate_models.documents.app.models.doc_images import DocImage", "from accelerate_models.documents.app.models.enum import DocumentStatus, DocumentType, ImageType", "from sqlalchemy import (", "    Column,", "    Integer,", "    MetaData,", "    Table,", "    Text,", "    delete,", "    select,", ")", "from sqlalchemy.dialects.postgresql import insert as pg_insert", "", "import common.models.all as Tables", "from common.helpers.doc_images_projection import (", "    write_doc_images_from_article_images as core_write_doc_images_from_article_images,", ")", "from common.models.enums import ArticleType, OrganizationType", "from db.session_manager_async import (", "    sessionmanager_accelerate,", "    sessionmanager_datalake,", "    sessionmanager_master_db,", ")", "from microservices.entity_classification.config import config as ec_config", "from microservices.entity_classification.schemas.match_objects import (", "    EntityType as MatchEntityType,", ")", "from microservices.entity_classification.schemas.match_objects import (", "    MatchedOrganizationObj,", "    MatchedPersonObj,", ")", "from microservices.entity_classification.schemas.merged_organizations import OrganizationMerged", "from microservices.entity_classification.schemas.merged_people import PersonMerged", "from microservices.entity_classification.services.helpers.external.accelerate_table_writes import (", "    build_doc_entity_reasons,", "    write_doc_entity_map_entries,", "    write_doc_images_from_article_images,", ")", "from microservices.entity_classification.services.helpers.external.sync import (", "    sync_platform_records_and_pdf,", ")", "from microservices.entity_classification.services.helpers.table_writes import (", "    create_entity_rows,", "    create_industry_rows,", "    create_matched_entity,", "    write_doc_article_map_row,", ")", "from microservices.web_extraction.models import ArticleImage", "from microservices.web_extraction.models.enums import (", "    ArticleImageRejectionReason,", "    ArticleImageRole,", "    ArticleImageStatus,", ")", "", "from .._shared.preseeding import preseed_article, preseed_ec_l1_activities", "from .pretest import preseed_for_test, send_layer_one_messages", "", "pytestmark = pytest.mark.integration", "", "# Lightweight cvw.corporations table for seeding without triggering the", "# accelerate_models ORM mapper-configure (mirrors the conftest IVWIndustries seed).", "_CVW_METADATA = MetaData()", "_CvwCorporations = Table(", "    \"corporations\",", "    _CVW_METADATA,", "    Column(\"id\", Integer, primary_key=True),", "    Column(\"name\", Text, nullable=False),", "    schema=\"cvw\",", ")", "", "# DAT-6954: corp ids carried only on original_id provenance (no source-map pio_id).", "_FRONTIER_CORP_ID = 3572  # org via pio.entity_master", "_CEO_COMPANY_CORP_ID = 28  # person/CEO via refinitiv.ceos -> their company's corp_id", "", "", "async def _seed_corporations(rows: list[dict]) -> None:", "    \"\"\"Seed cvw.corporations rows (idempotent) so AC3 validation passes.\"\"\"", "    async with sessionmanager_accelerate.session() as session:", "        await session.execute(", "            pg_insert(_CvwCorporations)", "            .values(rows)", "            .on_conflict_do_nothing(index_elements=[_CvwCorporations.c.id])", "        )", "        await session.commit()", "", "", "async def _preseed_ec_l1_activity_ids_for_doc_map_test() -> tuple[UUID, list[UUID]]:", "    \"\"\"Preseed a valid article + EC L1 activity chain suitable for doc-map writes.\"\"\"", "    (", "        feed,", "        article_ids,", "        aiq_l1_activity_ids,", "        manual_upload_article_id,", "        manual_upload_account_id,", "        webex_l1_activity_id,", "        webex_l2_activity_ids,", "        webex_l3_activity_id,", "    ) = await preseed_for_test()", "", "    aiq_ids_for_send = aiq_l1_activity_ids.copy()", "    msg_ids = await send_layer_one_messages(", "        feed=feed,", "        article_ids=article_ids,", "        aiq_l1_activity_ids=aiq_ids_for_send,", "        manual_upload_article_id=manual_upload_article_id,", "        manual_upload_account_id=manual_upload_account_id,", "        webex_l1_activity_id=webex_l1_activity_id,", "        webex_l2_activity_ids=webex_l2_activity_ids,", "        webex_l3_activity_id=webex_l3_activity_id,", "    )", "", "    async with sessionmanager_datalake.session() as session:", "        _, ec_l1_activity_ids = await preseed_ec_l1_activities(", "            db=session,", "            sqs_msg_ids=msg_ids,", "            aiq_l1_activity_ids=aiq_l1_activity_ids,", "        )", "", "    return manual_upload_article_id, ec_l1_activity_ids", "", "", "async def _create_accelerate_document_for_article(article_id: UUID) -> int:", "    \"\"\"Create a test accelerate document linked to *article_id* and return doc_id.\"\"\"", "    async with sessionmanager_accelerate.session() as acc_session:", "        doc_content = DocContent(", "            title_hash=str(uuid4()),", "            doc_hash=str(uuid4()),", "            doc_text=\"test content\",", "        )", "        acc_session.add(doc_content)", "        await acc_session.flush()", "", "        document = Document(", "            doc_type=DocumentType.NEWS_FEED,", "            title=\"doc image test\",", "            s3_bucket=\"bucket\",", "            s3_key=\"key\",", "            file_type=\"pdf\",", "            doc_info={\"article_id\": str(article_id), \"source\": \"entity_classification\"},", "            doc_content_id=doc_content.id,", "            status=DocumentStatus.QUESTIONING,", "        )", "        acc_session.add(document)", "        await acc_session.commit()", "        await acc_session.refresh(document)", "        return document.id", "", "", "@pytest.mark.asyncio", "async def test_doc_article_map_allows_same_article_multiple_doc_ids():", "    \"\"\"Same article_id with different doc_id values should persist both mappings.\"\"\"", "    article_id, ec_l1_activity_ids = await _preseed_ec_l1_activity_ids_for_doc_map_test()", "    assert len(ec_l1_activity_ids) >= 3, \"Expected at least three EC L1 activities for replay test\"", "    first_doc_id = 991001", "    second_doc_id = 991002", "", "    async with sessionmanager_datalake.session() as session:", "        first_return = await write_doc_article_map_row(", "            session,", "            article_id=article_id,", "            activity_id=ec_l1_activity_ids[0],", "            doc_id=first_doc_id,", "        )", "        second_return = await write_doc_article_map_row(", "            session,", "            article_id=article_id,", "            activity_id=ec_l1_activity_ids[1],", "            doc_id=second_doc_id,", "        )", "        replay_return = await write_doc_article_map_row(", "            session,", "            article_id=article_id,", "            activity_id=ec_l1_activity_ids[2],", "            doc_id=first_doc_id,", "        )", "", "        rows = (", "            (", "                await session.execute(", "                    select(Tables.DocArticleMap).where(", "                        Tables.DocArticleMap.article_id == article_id", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "    assert first_return == first_doc_id", "    assert second_return == second_doc_id", "    assert replay_return == first_doc_id", "", "    # After the constraint change to UNIQUE(article_id, doc_id, layer_one_activity_id),", "    # the third write creates a new row because it has a different activity_id,", "    # preserving the history of each activity's document mapping.", "    assert len(rows) == 3", "    assert {(row.article_id, row.doc_id, row.layer_one_activity_id) for row in rows} == {", "        (article_id, first_doc_id, ec_l1_activity_ids[0]),", "        (article_id, second_doc_id, ec_l1_activity_ids[1]),", "        (article_id, first_doc_id, ec_l1_activity_ids[2]),", "    }", "", "", "@pytest.mark.asyncio", "async def test_create_entity_rows_updates_on_conflict_person_org_location():", "    \"\"\"Reprocessing should refresh mutable fields for person/org/location rows.\"\"\"", "    article_id, ec_l1_activity_ids = await _preseed_ec_l1_activity_ids_for_doc_map_test()", "    activity_id = ec_l1_activity_ids[0]", "", "    async with sessionmanager_datalake.session() as session:", "        old_match = await create_matched_entity(", "            session,", "            article_id=article_id,", "            master_text_id=50001,", "            nvw_entity_id=60001,", "            entity_source_map_id=None,", "            entity_context_id=None,", "            priority=0.1,", "            normalized_text=\"old\",", "            normalization_version=\"v1\",", "            layer_one_activity_id=activity_id,", "        )", "        new_match = await create_matched_entity(", "            session,", "            article_id=article_id,", "            master_text_id=50002,", "            nvw_entity_id=60002,", "            entity_source_map_id=None,", "            entity_context_id=None,", "            priority=0.9,", "            normalized_text=\"new\",", "            normalization_version=\"v2\",", "            layer_one_activity_id=activity_id,", "        )", "", "        await create_entity_rows(", "            session,", "            [", "                Tables.Person(", "                    article_id=article_id,", "                    matched_entity_id=old_match.id,", "                    first_name=\"Alex\",", "                    middle_initial=\"Q\",", "                    last_name=\"Stone\",", "                    is_owner=False,", "                    evidence=[{\"source\": \"old-person\"}],", "                )", "            ],", "        )", "        await create_entity_rows(", "            session,", "            [", "                Tables.Organization(", "                    article_id=article_id,", "                    matched_entity_id=old_match.id,", "                    name=\"Acme Co\",", "                    evidence=[{\"source\": \"old-org\"}],", "                    org_type=OrganizationType.COMPANY,", "                    org_type_evidence=\"old-org-type\",", "                )", "            ],", "        )", "        await create_entity_rows(", "            session,", "            [", "                Tables.Location(", "                    article_id=article_id,", "                    city=\"Austin\",", "                    region=\"Travis County\",", "                    state=\"TX\",", "                    evidence=[{\"source\": \"old-location\"}],", "                )", "            ],", "        )", "", "        await create_entity_rows(", "            session,", "            [", "                Tables.Person(", "                    article_id=article_id,", "                    matched_entity_id=new_match.id,", "                    first_name=\"Alex\",", "                    middle_initial=\"Q\",", "                    last_name=\"Stone\",", "                    is_owner=True,", "                    evidence=[{\"source\": \"new-person\"}],", "                )", "            ],", "        )", "        await create_entity_rows(", "            session,", "            [", "                Tables.Organization(", "                    article_id=article_id,", "                    matched_entity_id=new_match.id,", "                    name=\"Acme Co\",", "                    evidence=[{\"source\": \"new-org\"}],", "                    org_type=OrganizationType.BRAND,", "                    org_type_evidence=\"new-org-type\",", "                )", "            ],", "        )", "        await create_entity_rows(", "            session,", "            [", "                Tables.Location(", "                    article_id=article_id,", "                    city=\"Austin\",", "                    region=\"Travis County\",", "                    state=\"TX\",", "                    evidence=[{\"source\": \"new-location\"}],", "                )", "            ],", "        )", "", "        person_row = await session.scalar(", "            select(Tables.Person).where(", "                Tables.Person.article_id == article_id,", "                Tables.Person.first_name == \"Alex\",", "                Tables.Person.middle_initial == \"Q\",", "                Tables.Person.last_name == \"Stone\",", "            )", "        )", "        org_row = await session.scalar(", "            select(Tables.Organization).where(", "                Tables.Organization.article_id == article_id,", "                Tables.Organization.name == \"Acme Co\",", "            )", "        )", "        location_row = await session.scalar(", "            select(Tables.Location).where(", "                Tables.Location.article_id == article_id,", "                Tables.Location.city == \"Austin\",", "                Tables.Location.region == \"Travis County\",", "                Tables.Location.state == \"TX\",", "            )", "        )", "", "    assert person_row is not None", "    assert org_row is not None", "    assert location_row is not None", "    assert person_row.matched_entity_id == new_match.id", "    assert person_row.is_owner is True", "    assert person_row.evidence == [{\"source\": \"new-person\"}]", "    assert org_row.matched_entity_id == new_match.id", "    assert org_row.evidence == [{\"source\": \"new-org\"}]", "    assert org_row.org_type == OrganizationType.BRAND", "    assert org_row.org_type_evidence == \"new-org-type\"", "    assert location_row.evidence == [{\"source\": \"new-location\"}]", "", "", "@pytest.mark.asyncio", "async def test_org_type_round_trips_all_enum_values():", "    \"\"\"Every OrganizationType member round-trips through the org_type Postgres ENUM.", "", "    Guards the DAT-6570 enum relocation: the Postgres ENUM labels in", "    entity_classification.org_type are unchanged, so each Python member should", "    serialize on insert and deserialize on read via the ENUM(OrganizationType,", "    name='org_type') column mapping.", "    \"\"\"", "    article_id, _ = await _preseed_ec_l1_activity_ids_for_doc_map_test()", "    members = list(OrganizationType)", "", "    async with sessionmanager_datalake.session() as session:", "        for member in members:", "            await create_entity_rows(", "                session,", "                [", "                    Tables.Organization(", "                        article_id=article_id,", "                        name=f\"Org-{member.name}\",", "                        evidence=[{\"source\": f\"round-trip-{member.name}\"}],", "                        org_type=member,", "                        org_type_evidence=f\"evidence-{member.name}\",", "                    )", "                ],", "            )", "", "        rows = (", "            await session.scalars(", "                select(Tables.Organization)", "                .where(Tables.Organization.article_id == article_id)", "                .where(Tables.Organization.name.like(\"Org-%\"))", "            )", "        ).all()", "", "    by_name = {r.name: r for r in rows}", "    assert set(by_name) == {f\"Org-{m.name}\" for m in members}", "    for member in members:", "        row = by_name[f\"Org-{member.name}\"]", "        assert isinstance(row.org_type, OrganizationType)", "        assert row.org_type == member", "", "", "@pytest.mark.asyncio", "async def test_create_industry_rows_updates_on_conflict():", "    \"\"\"Reprocessing should refresh mutable fields for industry rows.\"\"\"", "    async with sessionmanager_datalake.session() as session:", "        _, article_ids = await preseed_article(session, num_articles=1)", "        article_id = article_ids[0]", "", "        await create_industry_rows(", "            session,", "            [", "                Tables.ArticleIndustry(", "                    article_id=article_id,", "                    industry_id=27,", "                    industry_name=\"Apparel\",", "                    matched_entities=[\"old-entity\"],", "                    matched_entity_ids=[101],", "                )", "            ],", "        )", "        await create_industry_rows(", "            session,", "            [", "                Tables.ArticleIndustry(", "                    article_id=article_id,", "                    industry_id=27,", "                    industry_name=\"Apparel Updated\",", "                    matched_entities=[\"new-entity-a\", \"new-entity-b\"],", "                    matched_entity_ids=[202, 303],", "                )", "            ],", "        )", "", "        industry_row = await session.scalar(", "            select(Tables.ArticleIndustry).where(", "                Tables.ArticleIndustry.article_id == article_id,", "                Tables.ArticleIndustry.industry_id == 27,", "            )", "        )", "", "    assert industry_row is not None", "    assert industry_row.industry_name == \"Apparel Updated\"", "    assert industry_row.matched_entities == [\"new-entity-a\", \"new-entity-b\"]", "    assert industry_row.matched_entity_ids == [202, 303]", "", "", "async def _seed_image_rows(", "    article_id: UUID,", "    *,", "    rows: list[dict],", "    sentinel: datetime | None = datetime(2026, 4, 16, 12, 0, tzinfo=UTC),", ") -> None:", "    \"\"\"Insert article_images rows and (optionally) set the sentinel column.\"\"\"", "    async with sessionmanager_datalake.session() as dl_session:", "        for row_kwargs in rows:", "            dl_session.add(ArticleImage(article_id=article_id, **row_kwargs))", "        if sentinel is not None:", "            article_row = await dl_session.get(Tables.Article, article_id)", "            assert article_row is not None", "            article_row.images_processed_at = sentinel", "        await dl_session.commit()", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_prefers_s3_then_url_fallback():", "    \"\"\"DocImage helper should pick S3 keys when present, URL fallback otherwise.\"\"\"", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                source_url=\"https://example.com/source-main.jpg\",", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/example/main.jpg\",", "            ),", "            dict(", "                role=ArticleImageRole.THUMBNAIL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/example/thumbnail.jpg\",", "            ),", "        ],", "    )", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.ZYTE_ARTICLE,", "            )", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        s3_rows = (", "            (", "                await acc_session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "    assert len(s3_rows) == 2", "    rows_by_type = {row.image_type: row for row in s3_rows}", "    assert rows_by_type[ImageType.MAIN].s3_key == \"public/articles/2026-04-16/example/main.jpg\"", "    assert rows_by_type[ImageType.MAIN].url is None", "    assert (", "        rows_by_type[ImageType.THUMBNAIL].s3_key", "        == \"public/articles/2026-04-16/example/thumbnail.jpg\"", "    )", "    assert rows_by_type[ImageType.THUMBNAIL].url is None", "", "    # Replace rows so neither has an S3 key. Helper must fall back to source URL.", "    async with sessionmanager_datalake.session() as dl_session:", "        await dl_session.execute(delete(ArticleImage).where(ArticleImage.article_id == article_id))", "        await dl_session.commit()", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.FAILED,", "                rejection_reason=ArticleImageRejectionReason.S3_UPLOAD_FAILED,", "                source_url=\"https://example.com/source-main-only.jpg\",", "            ),", "        ],", "        sentinel=datetime(2026, 4, 16, 12, 5, tzinfo=UTC),", "    )", "", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.ZYTE_ARTICLE,", "            )", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        fallback_rows = (", "            (", "                await acc_session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "    # MAIN falls back to its source_url; THUMBNAIL has no own row and no", "    # fallback (the MAIN URL would be the full-res original, which is the", "    # wrong size for a thumbnail), so the THUMBNAIL doc_image is left", "    # unwritten and clients must fall back to MAIN themselves.", "    assert len(fallback_rows) == 1", "    fallback_by_type = {row.image_type: row for row in fallback_rows}", "    assert fallback_by_type[ImageType.MAIN].s3_key is None", "    assert fallback_by_type[ImageType.MAIN].url == \"https://example.com/source-main-only.jpg\"", "    assert ImageType.THUMBNAIL not in fallback_by_type", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_omits_thumbnail_when_only_main_succeeded():", "    \"\"\"MAIN SUCCEEDED + THUMBNAIL non-SUCCEEDED \u2192 no THUMBNAIL doc_image written.", "", "    Falling back to MAIN's source_url for THUMBNAIL would silently serve", "    the full-res original (often thousands of pixels wide) to clients", "    expecting a ~130px thumbnail. The helper now leaves the THUMBNAIL", "    row unwritten so clients can fall back to MAIN themselves.", "    \"\"\"", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                source_url=\"https://example.com/source-main.jpg\",", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/example/main.jpg\",", "            ),", "            dict(", "                role=ArticleImageRole.THUMBNAIL,", "                status=ArticleImageStatus.FAILED,", "                rejection_reason=ArticleImageRejectionReason.S3_UPLOAD_FAILED,", "            ),", "        ],", "    )", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.ZYTE_ARTICLE,", "            )", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        rows = (", "            (", "                await acc_session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "    assert len(rows) == 1", "    by_type = {row.image_type: row for row in rows}", "    assert by_type[ImageType.MAIN].s3_key == \"public/articles/2026-04-16/example/main.jpg\"", "    assert ImageType.THUMBNAIL not in by_type", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_projects_manual_upload_article_images(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"Manual upload MAIN + SUPPLEMENTAL project with source_index/position.", "", "    MAIN carries its true ordinal on ``source_index`` (NOT ``image_index``, which", "    is pinned 0), the SUPPLEMENTAL body image now projects a third ``doc_images``", "    row with matching ``source_index``/``position``, and THUMBNAIL is unchanged.", "    \"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    # MAIN's true document ordinal is non-zero so the assertion proves the", "    # projection reads source_index, not the pinned image_index (0).", "    main_source_index = 2", "    supplemental_source_index = 3", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                source_url=None,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/example/manual-main.jpg\",", "                image_index=0,", "                source_index=main_source_index,", "                position=0.1,", "            ),", "            dict(", "                role=ArticleImageRole.THUMBNAIL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/example/manual-thumbnail.jpg\",", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/example/manual-supplemental.jpg\",", "                image_index=1,", "                source_index=supplemental_source_index,", "                position=0.5,", "            ),", "        ],", "    )", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    loop = asyncio.get_running_loop()", "    started = loop.time()", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.MANUAL_UPLOAD,", "            )", "    elapsed = loop.time() - started", "", "    assert elapsed < 0.5", "    async with sessionmanager_accelerate.session() as acc_session:", "        rows = (", "            (", "                await acc_session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "    # AC2: the SUPPLEMENTAL body image now projects alongside MAIN + THUMBNAIL.", "    assert len(rows) == 3", "    by_type = {row.image_type: row for row in rows}", "    assert by_type[ImageType.MAIN].s3_key == \"public/articles/2026-04-16/example/manual-main.jpg\"", "    # AC4: MAIN carries its true ordinal (2), not the pinned image_index (0).", "    assert by_type[ImageType.MAIN].source_index == main_source_index", "    assert by_type[ImageType.MAIN].image_type == ImageType.MAIN", "    assert float(by_type[ImageType.MAIN].position) == pytest.approx(0.1)", "    # AC3: THUMBNAIL projection unchanged \u2014 no source_index/position stamped.", "    assert (", "        by_type[ImageType.THUMBNAIL].s3_key", "        == \"public/articles/2026-04-16/example/manual-thumbnail.jpg\"", "    )", "    assert by_type[ImageType.THUMBNAIL].source_index is None", "    assert by_type[ImageType.THUMBNAIL].position is None", "    supplemental = by_type[ImageType.SUPPLEMENTAL]", "    assert supplemental.s3_key == \"public/articles/2026-04-16/example/manual-supplemental.jpg\"", "    assert supplemental.source_index == supplemental_source_index", "    assert float(supplemental.position) == pytest.approx(0.5)", "", "", "async def _run_doc_image_projection(article_id: UUID, doc_id: int) -> None:", "    \"\"\"Run the doc_images projection for *article_id* onto *doc_id*.\"\"\"", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.MANUAL_UPLOAD,", "            )", "", "", "async def _fetch_doc_images(doc_id: int) -> list[DocImage]:", "    \"\"\"Return all doc_images rows for *doc_id* ordered by type then source_index.\"\"\"", "    async with sessionmanager_accelerate.session() as acc_session:", "        return (", "            (", "                await acc_session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc(), DocImage.source_index.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "", "def _supplemental_source_indexes(rows: list[DocImage]) -> set[int]:", "    return {r.source_index for r in rows if r.image_type == ImageType.SUPPLEMENTAL}", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_supplemental_projection_is_idempotent_on_redelivery(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"AC6: re-projecting the same image set yields identical rows (no duplicates).\"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/main.jpg\",", "                image_index=0,", "                source_index=0,", "                position=0.05,", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-1.jpg\",", "                image_index=1,", "                source_index=1,", "                position=0.4,", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-2.jpg\",", "                image_index=2,", "                source_index=2,", "                position=0.8,", "            ),", "        ],", "    )", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    await _run_doc_image_projection(article_id, doc_id)", "    first = await _fetch_doc_images(doc_id)", "    await _run_doc_image_projection(article_id, doc_id)", "    second = await _fetch_doc_images(doc_id)", "", "    def _identity(rows: list[DocImage]) -> set[tuple]:", "        return {(r.image_type, r.source_index, r.s3_key, r.url) for r in rows}", "", "    assert len(first) == 3", "    assert _identity(first) == _identity(second)", "    assert _supplemental_source_indexes(second) == {1, 2}", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_supplemental_shrunken_set_deletes_stale(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"AC6: a redelivery with fewer supplementals reclaims the dropped rows.\"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-1.jpg\",", "                image_index=1,", "                source_index=1,", "                position=0.4,", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-2.jpg\",", "                image_index=2,", "                source_index=2,", "                position=0.8,", "            ),", "        ],", "    )", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    await _run_doc_image_projection(article_id, doc_id)", "    assert _supplemental_source_indexes(await _fetch_doc_images(doc_id)) == {1, 2}", "", "    # Redelivery produces a smaller set: only source_index 1 survives.", "    async with sessionmanager_datalake.session() as dl_session:", "        await dl_session.execute(delete(ArticleImage).where(ArticleImage.article_id == article_id))", "        await dl_session.commit()", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-1.jpg\",", "                image_index=1,", "                source_index=1,", "                position=0.4,", "            ),", "        ],", "        sentinel=datetime(2026, 4, 16, 12, 5, tzinfo=UTC),", "    )", "", "    await _run_doc_image_projection(article_id, doc_id)", "    assert _supplemental_source_indexes(await _fetch_doc_images(doc_id)) == {1}", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_deletes_supplemental_with_null_source_index(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"A pre-existing NULL-source_index SUPPLEMENTAL row is reclaimed on re-projection.", "", "    Guards the ``source_index IS NULL OR NOT IN (...)`` delete predicate: without", "    the IS NULL arm, ``NULL NOT IN (...)`` is unknown and the row would survive.", "    \"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-1.jpg\",", "                image_index=1,", "                source_index=1,", "                position=0.4,", "            ),", "        ],", "    )", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    # Seed a stale SUPPLEMENTAL doc_images row with a NULL source_index (url", "    # payload satisfies ck_doc_images_s3_or_url).", "    async with sessionmanager_accelerate.session() as acc_session:", "        acc_session.add(", "            DocImage(", "                doc_id=doc_id,", "                image_type=ImageType.SUPPLEMENTAL,", "                source_index=None,", "                url=\"https://example.com/orphan-supp.jpg\",", "            )", "        )", "        await acc_session.commit()", "", "    await _run_doc_image_projection(article_id, doc_id)", "", "    rows = await _fetch_doc_images(doc_id)", "    supplemental = [r for r in rows if r.image_type == ImageType.SUPPLEMENTAL]", "    assert {r.source_index for r in supplemental} == {1}", "    assert all(r.url != \"https://example.com/orphan-supp.jpg\" for r in supplemental)", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_projects_supplemental_onto_new_doc_id(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"Different-account duplicate: existing article_images project onto a new doc_id.\"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/main.jpg\",", "                image_index=0,", "                source_index=0,", "                position=0.05,", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/supp-1.jpg\",", "                image_index=1,", "                source_index=1,", "                position=0.4,", "            ),", "        ],", "    )", "", "    doc_id_a = await _create_accelerate_document_for_article(article_id)", "    doc_id_b = await _create_accelerate_document_for_article(article_id)", "    assert doc_id_a != doc_id_b", "", "    await _run_doc_image_projection(article_id, doc_id_a)", "    await _run_doc_image_projection(article_id, doc_id_b)", "", "    rows_b = await _fetch_doc_images(doc_id_b)", "    by_type_b = {r.image_type: r for r in rows_b}", "    assert ImageType.MAIN in by_type_b", "    assert by_type_b[ImageType.MAIN].source_index == 0", "    assert _supplemental_source_indexes(rows_b) == {1}", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_short_circuits_when_sentinel_set_with_no_rows(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"Sentinel set but no rows means webex skipped image work; helper returns quickly.\"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "        article_row = await dl_session.get(Tables.Article, article_id)", "        assert article_row is not None", "        article_row.images_processed_at = datetime(2026, 4, 16, 12, 0, tzinfo=UTC)", "        await dl_session.commit()", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    loop = asyncio.get_running_loop()", "    started = loop.time()", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.ZYTE_ARTICLE,", "            )", "    elapsed = loop.time() - started", "", "    # The short-circuit is two DB round-trips; a lost short-circuit blocks for at", "    # least one 0.5s poll, so 0.4s separates the two paths.", "    assert elapsed < 0.4", "    async with sessionmanager_accelerate.session() as acc_session:", "        rows = (", "            (await acc_session.execute(select(DocImage).where(DocImage.doc_id == doc_id)))", "            .scalars()", "            .all()", "        )", "    # Both image_types are cleared (no s3 key, no url) since there's no data to project.", "    assert rows == []", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_waits_and_picks_up_s3_keys(monkeypatch: pytest.MonkeyPatch):", "    \"\"\"Helper should wait for the sentinel and pick up rows written mid-poll.\"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 2.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    async def _complete_image_processing() -> None:", "        await asyncio.sleep(0.1)", "        await _seed_image_rows(", "            article_id,", "            rows=[", "                dict(", "                    role=ArticleImageRole.MAIN,", "                    status=ArticleImageStatus.SUCCEEDED,", "                    source_url=\"https://example.com/main.jpg\",", "                    s3_bucket=\"bucket\",", "                    s3_key=\"public/articles/2026-04-16/example/main.jpg\",", "                ),", "                dict(", "                    role=ArticleImageRole.THUMBNAIL,", "                    status=ArticleImageStatus.SUCCEEDED,", "                    s3_bucket=\"bucket\",", "                    s3_key=\"public/articles/2026-04-16/example/thumbnail.jpg\",", "                ),", "            ],", "        )", "", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await asyncio.gather(", "                write_doc_images_from_article_images(", "                    dl_db=dl_session,", "                    acc_db=acc_session,", "                    article_id=article_id,", "                    doc_id=doc_id,", "                    article_type=ArticleType.ZYTE_ARTICLE,", "                ),", "                _complete_image_processing(),", "            )", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        rows = (", "            (", "                await acc_session.execute(", "                    select(DocImage)", "                    .where(DocImage.doc_id == doc_id)", "                    .order_by(DocImage.image_type.asc())", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "    assert len(rows) == 2", "    by_type = {row.image_type: row for row in rows}", "    assert by_type[ImageType.MAIN].s3_key == \"public/articles/2026-04-16/example/main.jpg\"", "    assert by_type[ImageType.THUMBNAIL].s3_key == \"public/articles/2026-04-16/example/thumbnail.jpg\"", "", "", "@pytest.mark.asyncio", "async def test_write_doc_images_times_out_with_no_rows_writes_nothing(", "    monkeypatch: pytest.MonkeyPatch,", "):", "    \"\"\"Timeout with no article_images rows means no fallback URL is available.", "", "    This is a behavior change from the JSONB era: the source URL used", "    to live in JSONB and was readable even before image processing", "    finished. Now it lives on the article_images row, which only", "    exists once webex has written outcomes. Timeout \u2192 empty doc_images.", "    \"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 0.0)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            await write_doc_images_from_article_images(", "                dl_db=dl_session,", "                acc_db=acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                article_type=ArticleType.ZYTE_ARTICLE,", "            )", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        rows = (", "            (await acc_session.execute(select(DocImage).where(DocImage.doc_id == doc_id)))", "            .scalars()", "            .all()", "        )", "", "    assert rows == []", "", "", "# ---------------------------------------------------------------------------", "# DAT-6954: CVW corp_id resolved from original_id provenance (no source-map row)", "# ---------------------------------------------------------------------------", "", "", "def _make_gap_org(", "    name: str, resolved_corp_id: int, source_table: str, priority: float", ") -> MatchedOrganizationObj:", "    \"\"\"Org matched to an entity with original_id provenance but no source-map row.\"\"\"", "    return MatchedOrganizationObj(", "        entity_text=name,", "        entity_type=MatchEntityType.ORGANIZATION,", "        entity_source_map_id=None,", "        resolved_corp_id=resolved_corp_id,", "        resolved_source_table=source_table,", "        organization_raw_data=OrganizationMerged(", "            organization_type=OrganizationType.COMPANY,", "            priority=priority,", "            confidence=0.9,", "        ),", "    )", "", "", "def _make_gap_person(", "    name: str, resolved_corp_id: int, source_table: str, priority: float", ") -> MatchedPersonObj:", "    \"\"\"CEO/officer person whose company corp_id lives only on original_id.\"\"\"", "    return MatchedPersonObj(", "        entity_text=name,", "        entity_type=MatchEntityType.PERSON,", "        entity_source_map_id=None,", "        resolved_corp_id=resolved_corp_id,", "        resolved_source_table=source_table,", "        person_raw_data=PersonMerged(priority=priority, is_owner=True, confidence=0.8),", "    )", "", "", "@pytest.mark.asyncio", "async def test_replay_writes_cvw_for_original_id_resolved_corp_ids():", "    \"\"\"Gap org + CEO person (corp_id only on original_id) get CVW doc_entity_map rows.", "", "    Regression for DAT-6954: entities whose corp_id lives only in", "    ``original_id->'id'->>'value'`` (no ``entities_source_map`` pio_id row) were", "    silently dropped, producing no CVW attribution. After the fix the resolved", "    corp_id rides on the match object, survives AC3 validation against", "    ``cvw.corporations``, and produces a CVW row. IVW attribution is unchanged and", "    replay is idempotent.", "    \"\"\"", "    article_id, _ = await _preseed_ec_l1_activity_ids_for_doc_map_test()", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    await _seed_corporations(", "        [", "            {\"id\": _FRONTIER_CORP_ID, \"name\": f\"Frontier Airlines {uuid4().hex[:8]}\"},", "            {\"id\": _CEO_COMPANY_CORP_ID, \"name\": f\"JG Summit {uuid4().hex[:8]}\"},", "        ]", "    )", "", "    matched_orgs = [", "        _make_gap_org(\"Frontier Airlines\", _FRONTIER_CORP_ID, \"pio.entity_master\", priority=20.0)", "    ]", "    matched_people = [", "        _make_gap_person(\"Lance Gokongwei\", _CEO_COMPANY_CORP_ID, \"refinitiv.ceos\", priority=25.0)", "    ]", "    # An existing IVW match (industry 27 is seeded by the EC conftest) must be", "    # preserved unchanged alongside the new CVW rows.", "    matched_industries = [", "        Tables.ArticleIndustry(", "            article_id=article_id,", "            industry_id=27,", "            industry_name=\"Apparel & Accessories\",", "            matched_entities=[],", "            matched_entity_ids=[],", "        )", "    ]", "", "    def _build() -> list:", "        return build_doc_entity_reasons(", "            matched_people=matched_people,", "            matched_orgs=matched_orgs,", "            matched_locs=[],", "            matched_industries=matched_industries,", "            matched_text_by_id={},", "        )", "", "    # First write.", "    async with sessionmanager_accelerate.session() as acc_session:", "        await write_doc_entity_map_entries(acc_session, doc_id=doc_id, reasons=_build())", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        first_rows = (", "            (await acc_session.execute(select(DocEntityMap).where(DocEntityMap.doc_id == doc_id)))", "            .scalars()", "            .all()", "        )", "", "    cvw_corp_ids = {r.corp_id for r in first_rows if r.entity_type == AccountType.CVW}", "    ivw_industry_ids = {r.industry_id for r in first_rows if r.entity_type == AccountType.IVW}", "", "    # AC1: both resolved corp_ids produce CVW rows.", "    assert _FRONTIER_CORP_ID in cvw_corp_ids", "    assert _CEO_COMPANY_CORP_ID in cvw_corp_ids", "    # R5: IVW attribution is unchanged.", "    assert ivw_industry_ids == {27}", "", "    # Replay: writing the same reasons again is idempotent (no duplicates).", "    async with sessionmanager_accelerate.session() as acc_session:", "        await write_doc_entity_map_entries(acc_session, doc_id=doc_id, reasons=_build())", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        replay_rows = (", "            (await acc_session.execute(select(DocEntityMap).where(DocEntityMap.doc_id == doc_id)))", "            .scalars()", "            .all()", "        )", "", "    assert len(replay_rows) == len(first_rows)", "    replay_keys = {(r.entity_type, r.corp_id, r.market_id, r.industry_id) for r in replay_rows}", "    first_keys = {(r.entity_type, r.corp_id, r.market_id, r.industry_id) for r in first_rows}", "    assert replay_keys == first_keys", "", "", "@pytest.mark.asyncio", "async def test_replay_skips_unknown_corp_id_and_keeps_valid():", "    \"\"\"AC3: a resolved corp_id absent from cvw.corporations is skipped, valid kept.", "", "    The unknown corp_id is dropped at FK pre-validation (no FK-violation, no row);", "    the valid corp_id still produces its CVW row.", "    \"\"\"", "    article_id, _ = await _preseed_ec_l1_activity_ids_for_doc_map_test()", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    unknown_corp_id = 99_000_000  # not seeded into cvw.corporations", "    await _seed_corporations([{\"id\": _FRONTIER_CORP_ID, \"name\": f\"Frontier {uuid4().hex[:8]}\"}])", "", "    matched_orgs = [", "        _make_gap_org(\"Frontier Airlines\", _FRONTIER_CORP_ID, \"pio.entity_master\", priority=20.0),", "        _make_gap_org(\"Ghost Corp\", unknown_corp_id, \"pio.entity_master\", priority=20.0),", "    ]", "", "    reasons = build_doc_entity_reasons(", "        matched_people=[],", "        matched_orgs=matched_orgs,", "        matched_locs=[],", "        matched_industries=[],", "        matched_text_by_id={},", "    )", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        await write_doc_entity_map_entries(acc_session, doc_id=doc_id, reasons=reasons)", "", "    async with sessionmanager_accelerate.session() as acc_session:", "        rows = (", "            (await acc_session.execute(select(DocEntityMap).where(DocEntityMap.doc_id == doc_id)))", "            .scalars()", "            .all()", "        )", "", "    corp_ids = {r.corp_id for r in rows if r.entity_type == AccountType.CVW}", "    assert _FRONTIER_CORP_ID in corp_ids", "    assert unknown_corp_id not in corp_ids", "", "", "# ---------------------------------------------------------------------------", "# Manual-upload sync-path reachability (sync_platform_records_and_pdf)", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.asyncio", "async def test_manual_upload_sync_path_projects_doc_images(monkeypatch: pytest.MonkeyPatch):", "    \"\"\"Both manual-upload forks of sync_platform_records_and_pdf land doc_images rows.", "", "    Drives the real sync entrypoint (not the projection helper) so a regression", "    that unwires the projection from the manual-upload path fails here.", "    \"\"\"", "    monkeypatch.setattr(ec_config, \"IMAGE_WAIT_TIMEOUT_SECONDS\", 30.0)", "", "    (", "        feed,", "        article_ids,", "        aiq_l1_activity_ids,", "        manual_upload_article_id,", "        manual_upload_account_id,", "        webex_l1_activity_id,", "        webex_l2_activity_ids,", "        webex_l3_activity_id,", "    ) = await preseed_for_test()", "", "    await _seed_image_rows(", "        manual_upload_article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/manual-main.png\",", "                image_index=0,", "                source_index=0,", "                position=0.05,", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/manual-supp-1.png\",", "                image_index=1,", "                source_index=1,", "                position=0.4,", "            ),", "        ],", "    )", "", "    async def _drive_sync() -> int | None:", "        async with sessionmanager_datalake.session() as dl_session:", "            async with sessionmanager_master_db.session() as master_session:", "                async with sessionmanager_accelerate.session() as acc_session:", "                    return await sync_platform_records_and_pdf(", "                        datalake_db=dl_session,", "                        master_db=master_session,", "                        accelerate_db=acc_session,", "                        article_id=manual_upload_article_id,", "                        article_type=ArticleType.MANUAL_UPLOAD,", "                        matched_people=[],", "                        matched_orgs=[],", "                        matched_locs=[],", "                        article_industries=[],", "                        manual_upload_account_id=manual_upload_account_id,", "                        api_helper=None,", "                        openai_api_key=None,", "                    )", "", "    # New-doc fork: no doc_article_map row exists yet for this upload.", "    doc_id = await _drive_sync()", "    assert doc_id is not None", "", "    rows = await _fetch_doc_images(doc_id)", "    main_rows = [r for r in rows if r.image_type == ImageType.MAIN]", "    assert len(main_rows) == 1", "    assert main_rows[0].source_index == 0", "    assert _supplemental_source_indexes(rows) == {1}", "", "    # Reuse fork: the EC service records the doc_article_map row after a", "    # successful sync; replaying the same upload must re-project idempotently.", "    msg_ids = await send_layer_one_messages(", "        feed=feed,", "        article_ids=article_ids,", "        aiq_l1_activity_ids=aiq_l1_activity_ids.copy(),", "        manual_upload_article_id=manual_upload_article_id,", "        manual_upload_account_id=manual_upload_account_id,", "        webex_l1_activity_id=webex_l1_activity_id,", "        webex_l2_activity_ids=webex_l2_activity_ids,", "        webex_l3_activity_id=webex_l3_activity_id,", "    )", "    async with sessionmanager_datalake.session() as session:", "        _, ec_l1_activity_ids = await preseed_ec_l1_activities(", "            db=session,", "            sqs_msg_ids=msg_ids,", "            aiq_l1_activity_ids=aiq_l1_activity_ids,", "        )", "    async with sessionmanager_datalake.session() as session:", "        await write_doc_article_map_row(", "            db=session,", "            article_id=manual_upload_article_id,", "            activity_id=ec_l1_activity_ids[0],", "            doc_id=doc_id,", "            manual_upload_account_id=manual_upload_account_id,", "        )", "", "    reuse_doc_id = await _drive_sync()", "    assert reuse_doc_id == doc_id", "", "    rows_after_replay = await _fetch_doc_images(doc_id)", "    assert len(rows_after_replay) == len(rows)", "    assert _supplemental_source_indexes(rows_after_replay) == {1}", "", "", "@pytest.mark.asyncio", "async def test_core_projection_result_matches_the_persisted_rows():", "    \"\"\"The shared core's result value reports exactly what it persisted.", "", "    Called directly (not through the EC wrapper) because the result value is the", "    core's own contract \u2014 web_extraction L3 logs from it to explain why a", "    duplicate document has no image.", "    \"\"\"", "    async with sessionmanager_datalake.session() as dl_session:", "        _, article_ids = await preseed_article(dl_session, num_articles=1)", "        article_id = article_ids[0]", "", "    await _seed_image_rows(", "        article_id,", "        rows=[", "            dict(", "                role=ArticleImageRole.MAIN,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/core/main.jpg\",", "                source_index=0,", "            ),", "            dict(", "                role=ArticleImageRole.THUMBNAIL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/core/thumbnail.jpg\",", "            ),", "            dict(", "                role=ArticleImageRole.SUPPLEMENTAL,", "                status=ArticleImageStatus.SUCCEEDED,", "                s3_bucket=\"bucket\",", "                s3_key=\"public/articles/2026-04-16/core/supplemental-1.jpg\",", "                image_index=1,", "                source_index=1,", "            ),", "        ],", "    )", "", "    doc_id = await _create_accelerate_document_for_article(article_id)", "", "    async with sessionmanager_datalake.session() as dl_session:", "        async with sessionmanager_accelerate.session() as acc_session:", "            result = await core_write_doc_images_from_article_images(", "                dl_session,", "                acc_session,", "                article_id=article_id,", "                doc_id=doc_id,", "                timeout_seconds=0.1,", "            )", "", "    rows = await _fetch_doc_images(doc_id)", "    rows_by_type = {row.image_type: row for row in rows}", "", "    assert result.sentinel_seen is True", "    assert result.source_rows_loaded == 3", "    assert result.main_written is (ImageType.MAIN in rows_by_type)", "    assert result.thumbnail_written is (ImageType.THUMBNAIL in rows_by_type)", "    assert result.supplemental_written == len(_supplemental_source_indexes(rows))", "    assert result.wrote_any is True", "    assert len(rows) == 3"], "blocks": [{"start": 1, "end": 82, "label": "Imports and module setup"}, {"start": 83, "end": 93, "label": "def _seed_corporations"}, {"start": 94, "end": 128, "label": "def _preseed_ec_l1_activity_ids_for_doc_map_test"}, {"start": 129, "end": 155, "label": "def _create_accelerate_document_for_article"}, {"start": 156, "end": 210, "label": "def test_doc_article_map_allows_same_article_multiple_doc_ids"}, {"start": 211, "end": 358, "label": "def test_create_entity_rows_updates_on_conflict_person_org_location"}, {"start": 359, "end": 401, "label": "def test_org_type_round_trips_all_enum_values"}, {"start": 402, "end": 446, "label": "def test_create_industry_rows_updates_on_conflict"}, {"start": 447, "end": 463, "label": "def _seed_image_rows"}, {"start": 464, "end": 576, "label": "def test_write_doc_images_prefers_s3_then_url_fallback"}, {"start": 577, "end": 638, "label": "def test_write_doc_images_omits_thumbnail_when_only_main_succeeded"}, {"start": 639, "end": 739, "label": "def test_write_doc_images_projects_manual_upload_article_images"}, {"start": 740, "end": 752, "label": "def _run_doc_image_projection"}, {"start": 753, "end": 768, "label": "def _fetch_doc_images"}, {"start": 769, "end": 772, "label": "def _supplemental_source_indexes"}, {"start": 773, "end": 830, "label": "def test_write_doc_images_supplemental_projection_is_idempotent_on_redelivery"}, {"start": 831, "end": 893, "label": "def test_write_doc_images_supplemental_shrunken_set_deletes_stale"}, {"start": 894, "end": 945, "label": "def test_write_doc_images_deletes_supplemental_with_null_source_index"}, {"start": 946, "end": 994, "label": "def test_write_doc_images_projects_supplemental_onto_new_doc_id"}, {"start": 995, "end": 1037, "label": "def test_write_doc_images_short_circuits_when_sentinel_set_with_no_rows"}, {"start": 1038, "end": 1101, "label": "def test_write_doc_images_waits_and_picks_up_s3_keys"}, {"start": 1102, "end": 1145, "label": "def test_write_doc_images_times_out_with_no_rows_writes_nothing"}, {"start": 1146, "end": 1163, "label": "def _make_gap_org"}, {"start": 1164, "end": 1177, "label": "def _make_gap_person"}, {"start": 1178, "end": 1262, "label": "def test_replay_writes_cvw_for_original_id_resolved_corp_ids"}, {"start": 1263, "end": 1308, "label": "def test_replay_skips_unknown_corp_id_and_keeps_valid"}, {"start": 1309, "end": 1416, "label": "def test_manual_upload_sync_path_projects_doc_images"}, {"start": 1417, "end": 1477, "label": "def test_core_projection_result_matches_the_persisted_rows"}], "lineCount": 1477, "sha256": "600fbaa8c5ca254da1cccd04f0ac73eed559aa6dbec6b2e1f72499bdef1ee58d", "endsWithNewline": true});
